                poly[i] += 1
        return poly

    def twisted_quotient_algebra(poly, n):
        algebra = []
        for i in range(2**n):
            row = [0] * (2**n)
            for j in range(2**n):
                if sum(poly[k] for k in range(n) if i & (1 << k)) % 2 == poly[j]:
                    row[j] += 1
            algebra.append(row)
        return algebra

