                return len(path)
            i = next(j for j, x in enumerate(instance) if x != 0)
            stack.append((instance[:i] + [0] + instance[i+1:], path + ['F']))
            stack.append((instance[:i] + [1] + instance[i+1:], path + ['T']))
        return float('inf')

